content.query:
let logs = traces
| where timestamp {TimeRange}
| extend Category = tostring(customDimensions.CategoryName);
let translations = toscalar(logs | where Category == 'FlashCardSage.Api.Controllers.TranslationsController' and message startswith 'Translated ' | summarize sum(itemCount));
let cachedTranslations = toscalar(logs | where Category == 'FlashCardSage.Api.Translation.CachedTranslator' and message startswith 'Found the translation' | summarize sum(itemCount));
let cachedPictures = toscalar(logs | where Category == 'FlashCardSage.Api.Images.CachedImageGenerator' and message startswith 'Found picture' | summarize sum(itemCount));
let newPictures = toscalar(logs | where Category == 'FlashCardSage.Api.Images.CachedImageGenerator' and message startswith 'Kept a new' | summarize sum(itemCount));
union
    (print Feature = 'Translation', Answered = coalesce(translations, 0), FromCache = coalesce(cachedTranslations, 0)),
    (print Feature = 'Pictures', Answered = coalesce(cachedPictures, 0) + coalesce(newPictures, 0), FromCache = coalesce(cachedPictures, 0))
| project Feature, Answered, ['From the cache'] = FromCache, ['From the model'] = Answered - FromCache,
    ['Cache hit %'] = iff(Answered == 0, real(null), round(100.0 * FromCache / Answered, 1))
